import 'package:codeguardian_core/codeguardian_core.dart';

import 'html_report.dart' show computeReportScore;

/// Severities ordered most to least serious, for sorting findings within a
/// category section.
const List<String> _severityDescending = ['critical', 'high', 'medium', 'low', 'info'];

const Map<String, String> _severityEmoji = {
  'critical': '🔴',
  'high': '🟠',
  'medium': '🟡',
  'low': '🔵',
  'info': '⚪',
};

/// Categories in a fixed, deterministic display order (matches [Category]'s
/// declaration order: most reviewer-relevant first).
const List<String> _categoryOrder = [
  'security',
  'privacy',
  'correctness',
  'performance',
  'style',
  'other',
];

const Map<String, String> _categoryEmoji = {
  'security': '🔒',
  'privacy': '🕵️',
  'correctness': '🐛',
  'performance': '⚡',
  'style': '🎨',
  'other': '📦',
};

/// Generates a Markdown report from canonical findings JSON (the shape
/// `Finding.toJson()` produces), optimized for posting as a PR/MR comment:
///
///  * A single summary line with the overall score (see
///    [computeReportScore]) and a severity breakdown.
///  * One collapsible `<details>` section per [Category] that has at least
///    one finding, each containing a table of its findings sorted by
///    severity (most severe first). Categories with zero findings are
///    omitted entirely to keep the comment short.
///
/// [generateMarkdownReportFromFindings] is a convenience overload for
/// callers that already have [Finding] objects.
String generateMarkdownReport(
  List<Map<String, dynamic>> findings, {
  String title = 'CodeGuardian AI Report',
  DateTime? generatedAt,
}) {
  final timestamp = (generatedAt ?? DateTime.now()).toUtc().toIso8601String();
  final buffer = StringBuffer()
    ..writeln('## $title')
    ..writeln();

  if (findings.isEmpty) {
    buffer
      ..writeln('**Score: 100/100** &middot; No findings. :white_check_mark:')
      ..writeln()
      ..writeln('<sub>Generated by CodeGuardian AI &middot; $timestamp</sub>');
    return buffer.toString();
  }

  final score = computeReportScore(findings);
  final countsBySeverity = <String, int>{};
  for (final finding in findings) {
    final severity = finding['severity'] as String? ?? 'info';
    countsBySeverity[severity] = (countsBySeverity[severity] ?? 0) + 1;
  }
  final severityBreakdown = _severityDescending
      .where((s) => (countsBySeverity[s] ?? 0) > 0)
      .map((s) => '${countsBySeverity[s]} ${_titleCase(s)}')
      .join(', ');

  buffer
    ..writeln(
      '**Score: ${score.toStringAsFixed(0)}/100** &middot; '
      '${findings.length} finding${findings.length == 1 ? '' : 's'} '
      '($severityBreakdown)',
    )
    ..writeln();

  final byCategory = <String, List<Map<String, dynamic>>>{};
  for (final finding in findings) {
    final category = finding['category'] as String? ?? 'other';
    byCategory.putIfAbsent(category, () => []).add(finding);
  }

  for (final category in _categoryOrder) {
    final categoryFindings = byCategory[category];
    if (categoryFindings == null || categoryFindings.isEmpty) continue;

    final sorted = [...categoryFindings]
      ..sort((a, b) {
        final rankA = _severityDescending.indexOf(a['severity'] as String? ?? 'info');
        final rankB = _severityDescending.indexOf(b['severity'] as String? ?? 'info');
        return rankA.compareTo(rankB);
      });

    buffer
      ..writeln('<details>')
      ..writeln(
        '<summary>${_categoryEmoji[category] ?? ''} ${_titleCase(category)} '
        '(${sorted.length})</summary>',
      )
      ..writeln()
      ..writeln('| Severity | Rule | Location | Message |')
      ..writeln('| --- | --- | --- | --- |');

    for (final finding in sorted) {
      final severity = finding['severity'] as String? ?? 'info';
      final ruleId = finding['ruleId'] as String? ?? '';
      final file = finding['file'] as String? ?? '';
      final line = finding['line'] ?? '';
      final message = finding['message'] as String? ?? '';
      buffer.writeln(
        '| ${_severityEmoji[severity] ?? ''} ${_titleCase(severity)} '
        '| `$ruleId` | `$file:$line` '
        '| ${_escapeMarkdownCell(message)} |',
      );
    }

    buffer
      ..writeln()
      ..writeln('</details>')
      ..writeln();
  }

  buffer.writeln('<sub>Generated by CodeGuardian AI &middot; $timestamp</sub>');
  return buffer.toString();
}

/// Convenience overload of [generateMarkdownReport] for callers that already
/// have [Finding] objects rather than decoded JSON.
String generateMarkdownReportFromFindings(
  List<Finding> findings, {
  String title = 'CodeGuardian AI Report',
  DateTime? generatedAt,
}) {
  return generateMarkdownReport(
    findings.map((f) => f.toJson()).toList(),
    title: title,
    generatedAt: generatedAt,
  );
}

/// Escapes text for safe embedding in a single Markdown table cell: pipes
/// would otherwise terminate the cell early, and raw newlines would break
/// the row onto multiple lines.
String _escapeMarkdownCell(String text) => text
    .replaceAll('|', r'\|')
    .replaceAll('\r\n', ' ')
    .replaceAll('\n', ' ');

String _titleCase(String value) =>
    value.isEmpty ? value : value[0].toUpperCase() + value.substring(1);
